import{_ as a,o as s,c as o,a0 as t}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"luarocks-admin make manifest","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks_admin_make_manifest.md","filePath":"luarocks_admin_make_manifest.md"}'),i={name:"luarocks_admin_make_manifest.md"};function n(r,e,c,l,p,u){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="luarocks-admin-make-manifest" tabindex="-1">luarocks-admin make manifest <a class="header-anchor" href="#luarocks-admin-make-manifest" aria-label="Permalink to &quot;luarocks-admin make manifest&quot;">​</a></h1><p>Compile a manifest file for a repository.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>luarocks-admin make-manifest [--local-tree] [&lt;repository&gt;]</code></p><p><code>&lt;repository&gt;</code>, if given, is a local repository pathname. If no argument is given, rebuilds the manifest for the local repository of installed packages.</p><p>This command is used to update the <a href="./manifest_file_format.html">manifest file</a> in a directory containing rocks. By publishing a directory in a web server containing rocks and a manifest file, one creates a remote repository - LuaRocks clients can then configure their <a href="./config_file_format.html">configuration files</a> to search this repository.</p><p>If <code>--local-tree</code> is passed, versioned versions of the manifest file are not created. Use this when rebuilding the manifest of a local rocks tree.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Suppose you wrote a rockspec for your module called &quot;LuaSomething&quot; and you want to publish a LuaRocks repository in your site. (Normally, you don&#39;t need to do this, just upload your rockspec to the public rocks repository, so that LuaRocks users can access your module without further configuration. But let&#39;s proceed with the example.) Your module, LuaSomething, is now installed in your local repository: you can find it at <code>~/.luarocks/rocks/luasomething/1.0-1/</code>. To prepare a public repository, let&#39;s first pack your new rock:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks pack luasomething</span></span></code></pre></div><p>If LuaSomething is a pure-Lua module, this will generate <code>luasomething-1.0-1.all.rock</code> - this is a portable rock. If it contains C code, it generated a non-portable rock, such as <code>luasomething-1.0-1.linux-x86.rock</code> (in the Linux case specifically, it&#39;s probably not a good idea to publish binary rocks as they most likely won&#39;t be portable across Linux distributions). As an alternative, run <a href="./luarocks_pack.html">luarocks pack</a> on the rockspec, to create a source rock:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks pack ~/.luarocks/rocks/luasomething/1.0-1/luasomething-1.0-1.rockspec</span></span></code></pre></div><p>This will create <code>luasomething-1.0-1.src.rock</code>.</p><p>Now, create a directory that we&#39;ll use to create your public repository, and copy the files you want to publish.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir ~/myrocksrepo</span></span>
<span class="line"><span>cp luasomething-1.0-1.src.rock ~/myrocksrepo</span></span>
<span class="line"><span>cp ~/.luarocks/rocks/luasomething/1.0-1/luasomething-1.0-1.rockspec ~/myrocksrepo</span></span></code></pre></div><p>Perhaps you may have also a Windows build of your rock, packed with <a href="./luarocks_pack.html">luarocks pack</a> on a Windows machine:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cp luasomething-1.0-1.win32-x86.rock ~/myrocksrepo</span></span></code></pre></div><p>Now create a manifest file for this directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks-admin make-manifest ~/myrocksrepo</span></span></code></pre></div><p>And we&#39;re done: you can now just copy these files and the generated manifest to a public directory in a web server and your users will be able to use your rock by adding the URL you published the files at to their &quot;repositories&quot; array in their LuaRocks configuration file.</p>`,20)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
